using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public struct ItemStack
{
    public int ItemId;
    public int Count;

    public ItemStack(int itemId, int count)
    {
        ItemId = itemId;
        Count = count;
    }
}

public class Inventory : MonoBehaviour
{
    [SerializeField] private int _maxSlots = 20;
    [SerializeField] private int _maxStackSize = 99;

    private readonly List<ItemStack> _slots = new List<ItemStack>();

    public event Action<int, int> InventoryChanged;

    public int MaxSlots => _maxSlots;
    public int MaxStackSize => _maxStackSize;
    public int SlotCount => _slots.Count;
    public IReadOnlyList<ItemStack> Slots => _slots;

    private void Awake()
    {
        _maxSlots = Mathf.Max(1, _maxSlots);
        _maxStackSize = Mathf.Max(1, _maxStackSize);
    }

    /// <summary>Adds up to <paramref name="amount"/> of <paramref name="itemId"/>. Returns how many items did not fit.</summary>
    public int TryAdd(int itemId, int amount)
    {
        if (amount <= 0)
        {
            return 0;
        }

        int remaining = amount;

        for (int i = 0; i < _slots.Count && remaining > 0; i++)
        {
            ItemStack stack = _slots[i];
            if (stack.ItemId != itemId)
            {
                continue;
            }

            int space = _maxStackSize - stack.Count;
            if (space <= 0)
            {
                continue;
            }

            int toAdd = Mathf.Min(space, remaining);
            stack.Count += toAdd;
            _slots[i] = stack;
            remaining -= toAdd;
        }

        while (remaining > 0 && _slots.Count < _maxSlots)
        {
            int toAdd = Mathf.Min(_maxStackSize, remaining);
            _slots.Add(new ItemStack(itemId, toAdd));
            remaining -= toAdd;
        }

        int added = amount - remaining;
        if (added > 0)
        {
            InventoryChanged?.Invoke(itemId, added);
        }

        return remaining;
    }

    /// <summary>Removes up to <paramref name="amount"/> of <paramref name="itemId"/>, never more than is held. Returns the shortfall that could not be removed.</summary>
    public int TryRemove(int itemId, int amount)
    {
        if (amount <= 0)
        {
            return 0;
        }

        int remaining = amount;

        for (int i = _slots.Count - 1; i >= 0 && remaining > 0; i--)
        {
            ItemStack stack = _slots[i];
            if (stack.ItemId != itemId)
            {
                continue;
            }

            int toRemove = Mathf.Min(stack.Count, remaining);
            stack.Count -= toRemove;
            remaining -= toRemove;

            if (stack.Count <= 0)
            {
                _slots.RemoveAt(i);
            }
            else
            {
                _slots[i] = stack;
            }
        }

        int removed = amount - remaining;
        if (removed > 0)
        {
            InventoryChanged?.Invoke(itemId, -removed);
        }

        return remaining;
    }

    public int GetCount(int itemId)
    {
        int total = 0;
        for (int i = 0; i < _slots.Count; i++)
        {
            if (_slots[i].ItemId == itemId)
            {
                total += _slots[i].Count;
            }
        }

        return total;
    }
}
