using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;

public class InventoryTests
{
    private Inventory CreateInventory(int maxSlots, int maxStackSize)
    {
        var go = new GameObject("Inventory");
        var inventory = go.AddComponent<Inventory>();
        var so = new UnityEditor.SerializedObject(inventory);
        so.FindProperty("_maxSlots").intValue = maxSlots;
        so.FindProperty("_maxStackSize").intValue = maxStackSize;
        so.ApplyModifiedPropertiesWithoutUndo();
        return inventory;
    }

    [Test]
    public void TryAdd_FitsWithinSingleStack_ReturnsZeroLeftover()
    {
        var inventory = CreateInventory(maxSlots: 5, maxStackSize: 10);

        int leftover = inventory.TryAdd(itemId: 1, amount: 4);

        Assert.AreEqual(0, leftover);
        Assert.AreEqual(4, inventory.GetCount(1));
        Assert.AreEqual(1, inventory.SlotCount);

        Object.DestroyImmediate(inventory.gameObject);
    }

    [Test]
    public void TryAdd_FillsExistingStackBeforeCreatingNewSlot()
    {
        var inventory = CreateInventory(maxSlots: 5, maxStackSize: 10);

        inventory.TryAdd(itemId: 1, amount: 3);
        inventory.TryAdd(itemId: 1, amount: 3);

        Assert.AreEqual(6, inventory.GetCount(1));
        Assert.AreEqual(1, inventory.SlotCount);

        Object.DestroyImmediate(inventory.gameObject);
    }

    [Test]
    public void TryAdd_WhenSlotsFull_ReturnsLeftoverThatDidNotFit()
    {
        var inventory = CreateInventory(maxSlots: 1, maxStackSize: 5);

        int leftover = inventory.TryAdd(itemId: 1, amount: 12);

        Assert.AreEqual(7, leftover);
        Assert.AreEqual(5, inventory.GetCount(1));
        Assert.AreEqual(1, inventory.SlotCount);

        Object.DestroyImmediate(inventory.gameObject);
    }

    [Test]
    public void TryAdd_SpillsIntoNewSlotWhenStackFull()
    {
        var inventory = CreateInventory(maxSlots: 2, maxStackSize: 5);

        int leftover = inventory.TryAdd(itemId: 1, amount: 8);

        Assert.AreEqual(0, leftover);
        Assert.AreEqual(8, inventory.GetCount(1));
        Assert.AreEqual(2, inventory.SlotCount);

        Object.DestroyImmediate(inventory.gameObject);
    }

    [Test]
    public void TryRemove_NeverRemovesMoreThanHeld_ReturnsShortfall()
    {
        var inventory = CreateInventory(maxSlots: 5, maxStackSize: 10);
        inventory.TryAdd(itemId: 1, amount: 5);

        int shortfall = inventory.TryRemove(itemId: 1, amount: 10);

        Assert.AreEqual(5, shortfall);
        Assert.AreEqual(0, inventory.GetCount(1));
        Assert.AreEqual(0, inventory.SlotCount);

        Object.DestroyImmediate(inventory.gameObject);
    }

    [Test]
    public void TryRemove_PartialAmount_LeavesRemainderAndReturnsZeroShortfall()
    {
        var inventory = CreateInventory(maxSlots: 5, maxStackSize: 10);
        inventory.TryAdd(itemId: 1, amount: 8);

        int shortfall = inventory.TryRemove(itemId: 1, amount: 3);

        Assert.AreEqual(0, shortfall);
        Assert.AreEqual(5, inventory.GetCount(1));

        Object.DestroyImmediate(inventory.gameObject);
    }

    [Test]
    public void TryRemove_UnknownItem_ReturnsFullAmountAsShortfall()
    {
        var inventory = CreateInventory(maxSlots: 5, maxStackSize: 10);

        int shortfall = inventory.TryRemove(itemId: 99, amount: 4);

        Assert.AreEqual(4, shortfall);

        Object.DestroyImmediate(inventory.gameObject);
    }

    [UnityTest]
    public IEnumerator Inventory_PersistsStateAcrossFrames()
    {
        var inventory = CreateInventory(maxSlots: 5, maxStackSize: 10);

        inventory.TryAdd(itemId: 1, amount: 6);
        yield return null;
        inventory.TryRemove(itemId: 1, amount: 2);
        yield return null;

        Assert.AreEqual(4, inventory.GetCount(1));

        Object.Destroy(inventory.gameObject);
    }
}
